    11→        user(login: $login) {
    12→          name
    13→          login
    14→          contributionsCollection {
    15→            totalCommitContributions
    16→          }
    17→          repositoriesContributedTo(first: 1, contributionTypes: [COMMIT, ISSUE, PULL_REQUEST, REPOSITORY]) {
    18→            totalCount
    19→          }
    20→          pullRequests(first: 1) {
    21→            totalCount
    22→          }
    23→          issues(first: 1) {
    24→            totalCount
    25→          }
    26→          followers {
    27→            totalCount
    28→          }
    29→          repositories(first: 100, ownerAffiliations: OWNER, isFork: false, orderBy: {direction: DESC, field: STARGAZERS}) {
    30→            totalCount
    31→            nodes {
    32→              stargazers {
    33→                totalCount
    34→              }
    35→            }
    36→          }
    37→        }
    38→      }
    39→      `,
    40→      variables,
    41→    },
    42→    {
