    48→async function fetchStats(username) {
    49→  if (!username) throw Error("Invalid username");
    50→
    51→  const stats = {
    52→    name: "",
    53→    totalPRs: 0,
    54→    totalCommits: 0,
    55→    totalIssues: 0,
    56→    totalStars: 0,
    57→    contributedTo: 0,
    58→    rank: { level: "C", score: 0 },
    59→  };
    60→
    61→  let res = await retryer(fetcher, { login: username });
    62→
    63→  if (res.data.errors) {
    64→    logger.error(res.data.errors);
    65→    throw Error(res.data.errors[0].message || "Could not fetch user");
    66→  }
    67→
    68→  const user = res.data.data.user;
    69→
    70→  stats.name = user.name || user.login;
    71→  stats.totalIssues = user.issues.totalCount;
    72→  stats.totalCommits = user.contributionsCollection.totalCommitContributions;
    73→  stats.totalPRs = user.pullRequests.totalCount;
    74→  stats.contributedTo = user.repositoriesContributedTo.totalCount;
    75→
    76→  stats.totalStars = user.repositories.nodes.reduce((prev, curr) => {
    77→    return prev + curr.stargazers.totalCount;
    78→  }, 0);
    79→
    80→  stats.rank = calculateRank({
    81→    totalCommits: stats.totalCommits,
    82→    totalRepos: user.repositories.totalCount,
    83→    followers: user.followers.totalCount,
    84→    contributions: stats.contributedTo,
    85→    stargazers: stats.totalStars,
    86→    prs: stats.totalPRs,
    87→    issues: stats.totalIssues,
    88→  });
    89→
    90→  return stats;
    91→}
    92→
    93→module.exports = fetchStats;
