    79→function FlexLayout({ items, gap, direction }) {
    80→  // filter() for filtering out empty strings
    81→  return items.filter(Boolean).map((item, i) => {
    82→    let transform = `translate(${gap * i}, 0)`;
    83→    if (direction === "column") {
    84→      transform = `translate(0, ${gap * i})`;
